-- Speglar det som lades på databasen 2026-09-15 via apply_migration i tolv delar:
--   cy1_families_from_catalogue_part_01  (backup, bort med 'cy1r', fyra familjer, CY1S schema/familj/parametrar)
--   cy1_families_from_catalogue_part_02  (CY1S värdelista, rensning)
--   cy1_families_from_catalogue_part_03  (CY1S regler 1–20)
--   cy1_families_from_catalogue_part_04  (CY1S regler 21–34, dokumentkarta, SMC-CY1R -> SMC-CY1S; CY1L schema/familj)
--   cy1_families_from_catalogue_part_05  (CY1L parametrar, värdelista, rensning)
--   cy1_families_from_catalogue_part_06  (CY1L regler 1–20)
--   cy1_families_from_catalogue_part_07  (CY1L regler 21–34, dokumentkarta; CY1H schema/familj/parametrar)
--   cy1_families_from_catalogue_part_08  (CY1H värdelista, rensning, regler 1–20)
--   cy1_families_from_catalogue_part_09  (CY1H regler 21–47, dokumentkarta; CY1F backup)
--   cy1_families_from_catalogue_part_10  (CY1F schema/familj/parametrar/värdelista, rensning)
--   cy1_families_from_catalogue_part_11  (CY1F regler 1–20)
--   cy1_families_from_catalogue_part_12  (CY1F regler 21–35, dokumentkarta)
-- Fingeravtryck efter körning, identiska med modellen (scripts/fingerprint-rules.ts <slug>):
--   cy1s  regler 34  md5 1f3d6279466d801da20508b06a924d1d  villkor 25b85f2d7b40955caef65acf58787b58
--         värden 50  md5 345f7043ba84251ae41b72a82be430b2  schema cfdab24005939208e406b5f3478c9e77
--   cy1l  regler 34  md5 6c3c51b0ffde57808d385fe903ac5394  villkor b2f21761e5d4baa5f578cb13358254ff
--         värden 49  md5 aba75955842c7d06e99ea47ae0fcc276  schema bc4bcda4935e5e19e2b42d809b8d864e
--   cy1h  regler 47  md5 bdcf45a7bec897985bc44bb68c4a9a09  villkor b4d7665dac6595058828a512353eed3e
--         värden 34  md5 8f03d1c4753df2b54b70b87bc165fdad  schema 15938c8d6e75ddf8eba8aaaa4e5e301f
--   cy1f  regler 35  md5 4820097ab01e9907ebb9e2715ba89cce  villkor 1bc03b090119e3ad9714721bf56ae1c0
--         värden 41  md5 eff13edcef0ac9057629c2c0d1036011  schema be2c9aaaab751634f675ea58264b7536
-- Verifierat live: /sv/configurator/cy1s bygger CY1S25-300Z-M9BW (nyckelns exempel, sida 1214),
-- cy1l CY1L25H-300-J79W (sida 1230), cy1h stoppar CY1H25-350 tills -XB10 väljs och bygger
-- CY1H25-350-XB10 (sida 1243), cy1f CY1F10R-300-M9BW (sida 1265); 'cy1r' är borta ur listan.
--
-- CY1: fyra familjer (CY1S, CY1L, CY1H, CY1F) ersätter den påhittade 'cy1r'.
-- GENERERAD ur src/lib/catalog/cy1.ts -- redigera inte för hand.
--
-- Serien CY1R finns inte i SMC:s kataloger (strängen förekommer 0 gånger i
-- de tre CY1-katalogerna); slidtyperna CY1S, CY1L, CY1H och CY1F har var sin
-- beställnyckel med olika positioner. Produktraden SMC-CY1R döps om till
-- SMC-CY1S med katalogens data; CY1L/CY1H/CY1F får inga produktrader.

begin;

create schema if not exists backup;
create table if not exists backup.cy1r_before_20260915 as
  select 'family' as sort, f.id::text as id, f.slug as k,
         coalesce(f.order_code_template, '') || ' | ' || coalesce(f.title, '') as v
  from configurator_families f where f.slug = 'cy1r'
  union all
  select 'param', p.id::text, p.param_key, p.label
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'cy1r'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'cy1r'
  union all
  select 'doc', d.source_file, d.family_slug, coalesce(d.doc_title, '')
  from knowledge_doc_families d where d.family_slug = 'cy1r'
  union all
  select 'product', p.id::text, p.sku, p.name || ' | ' || coalesce(p.description, '')
  from products p where p.sku = 'SMC-CY1R'
  union all
  select 'spec', s.id::text, s.key, s.value
  from product_specs s join products p on p.id = s.product_id where p.sku = 'SMC-CY1R';

-- Den påhittade familjen. knowledge_doc_families kaskaderar; produktraden
-- pekas om nedan.
delete from configurator_param_values v using configurator_params p, configurator_families f
  where v.param_id = p.id and p.family_id = f.id and f.slug = 'cy1r';
delete from configurator_params p using configurator_families f
  where p.family_id = f.id and f.slug = 'cy1r';
delete from configurator_families where slug = 'cy1r';

-- De fyra familjerna (raderna fylls på av respektive familjs migration).
insert into configurator_families (slug, name, title, category_slug)
values ('cy1s', 'CY1S', 'Magnetkopplad kolvstångslös cylinder, slidtyp med glidlager ø6–40', 'cylinder')
on conflict (slug) do update set name = excluded.name;
insert into configurator_families (slug, name, title, category_slug)
values ('cy1l', 'CY1L', 'Magnetkopplad kolvstångslös cylinder, slidtyp med kulbussning ø6–40', 'cylinder')
on conflict (slug) do update set name = excluded.name;
insert into configurator_families (slug, name, title, category_slug)
values ('cy1h', 'CY1H', 'Magnetkopplad kolvstångslös cylinder med linjärstyrning ø10–32', 'cylinder')
on conflict (slug) do update set name = excluded.name;
insert into configurator_families (slug, name, title, category_slug)
values ('cy1f', 'CY1F', 'Magnetkopplad kolvstångslös cylinder, låg styrd typ ø10–25', 'cylinder')
on conflict (slug) do update set name = excluded.name;

commit;


-- CY1S: beställnyckeln enligt SMC Magnetically Coupled Rodless Cylinder CY1S Series (sida 1214).
-- GENERERAD ur src/lib/catalog/cy1.ts -- redigera inte för hand.
--
-- Slidtyp med glidlager. Kod CY1S{anslutning}{ø}{gänga}-{slag}{ändstopp}Z-{givare}{kabel}{antal}-{special},
-- t.ex. CY1S25-300Z-M9BW (sida 1214) och CY1SG25-500Z (sida 1215).

begin;

create schema if not exists backup;
create table if not exists backup.cy1s_before_20260915 as
  select 'param' as sort, p.id::text as id, p.param_key as k, p.label as v
  from configurator_params p join configurator_families f on f.id = p.family_id
  where f.slug = 'cy1s'
  union all
  select 'value', v.id::text, v.code, v.label
  from configurator_param_values v
  join configurator_params p on p.id = v.param_id
  join configurator_families f on f.id = p.family_id
  where f.slug = 'cy1s'
  union all
  select 'family', f.id::text, f.slug, coalesce(f.order_code_template, '')
  from configurator_families f where f.slug = 'cy1s';

insert into config_schemas (schema_id, schema_json, title_sv, title_en, category_slug)
values ('SCHEMA-CY1S-V1', '{"version":"1.0","steps":[{"id":"bore","step":1,"title_sv":"Kolvdiameter","title_en":"Bore size","required":true,"type":"single_select","options":[{"v":"6","label":"ø6 mm"},{"v":"10","label":"ø10 mm"},{"v":"15","label":"ø15 mm"},{"v":"20","label":"ø20 mm"},{"v":"25","label":"ø25 mm"},{"v":"32","label":"ø32 mm"},{"v":"40","label":"ø40 mm"}]},{"id":"piping","step":2,"title_sv":"Anslutning (standard är en port per plåt)","title_en":"Piping (bilateral is standard)","required":false,"type":"single_select","options":[{"v":"G","label":"Centraliserad anslutning, båda portarna på plåt A (standard är en port per plåt)"}]},{"id":"port","step":3,"title_sv":"Portgänga","title_en":"Port thread type","required":false,"type":"single_select","options":[{"v":"TN","label":"Portgänga NPT (standard är Rc)"},{"v":"TF","label":"Portgänga G (standard är Rc)"}]},{"id":"stroke_mm","step":4,"title_sv":"Slaglängd","title_en":"Cylinder stroke","required":true,"type":"numeric","min":15,"max":1500,"unit":"mm"},{"id":"adjust","step":5,"title_sv":"Ändstopp (standard är gummibuffert i båda ändar)","title_en":"Stopper type (rubber bumper both ends is standard)","required":false,"type":"single_select","options":[{"v":"B","label":"Stötdämpare och justerbult i båda ändar (i stället för gummibuffertar)"},{"v":"BS","label":"Stötdämpare och justerbult på plåt A, gummibuffert på plåt B/C"}]},{"id":"switch","step":6,"title_sv":"Magnetgivare","title_en":"Auto switch","required":false,"type":"single_select","options":[{"v":"M9N","label":"D-M9N, 3-tråd NPN, rak"},{"v":"M9NV","label":"D-M9NV, 3-tråd NPN, vinklad"},{"v":"M9P","label":"D-M9P, 3-tråd PNP, rak"},{"v":"M9PV","label":"D-M9PV, 3-tråd PNP, vinklad"},{"v":"M9B","label":"D-M9B, 2-tråd, rak"},{"v":"M9BV","label":"D-M9BV, 2-tråd, vinklad"},{"v":"M9NW","label":"D-M9NW, NPN, tvåfärgsindikering, rak"},{"v":"M9NWV","label":"D-M9NWV, NPN, tvåfärgsindikering, vinklad"},{"v":"M9PW","label":"D-M9PW, PNP, tvåfärgsindikering, rak"},{"v":"M9PWV","label":"D-M9PWV, PNP, tvåfärgsindikering, vinklad"},{"v":"M9BW","label":"D-M9BW, 2-tråd, tvåfärgsindikering, rak"},{"v":"M9BWV","label":"D-M9BWV, 2-tråd, tvåfärgsindikering, vinklad"},{"v":"M9NA","label":"D-M9NA, NPN, vattentät, rak"},{"v":"M9NAV","label":"D-M9NAV, NPN, vattentät, vinklad"},{"v":"M9PA","label":"D-M9PA, PNP, vattentät, rak"},{"v":"M9PAV","label":"D-M9PAV, PNP, vattentät, vinklad"},{"v":"M9BA","label":"D-M9BA, 2-tråd, vattentät, rak"},{"v":"M9BAV","label":"D-M9BAV, 2-tråd, vattentät, vinklad"},{"v":"A96","label":"D-A96, reed 3-tråd, rak"},{"v":"A96V","label":"D-A96V, reed 3-tråd, vinklad"},{"v":"A93","label":"D-A93, reed 2-tråd, rak"},{"v":"A93V","label":"D-A93V, reed 2-tråd, vinklad"},{"v":"A90","label":"D-A90, reed utan indikering, rak"},{"v":"A90V","label":"D-A90V, reed utan indikering, vinklad"}]},{"id":"lead","step":7,"title_sv":"Givarens kabellängd (standard 0,5 m)","title_en":"Lead wire length (0.5 m is standard)","required":false,"type":"single_select","options":[{"v":"M","label":"1 m kabel"},{"v":"L","label":"3 m kabel"},{"v":"Z","label":"5 m kabel"}]},{"id":"count","step":8,"title_sv":"Antal givare","title_en":"Number of auto switches","required":false,"type":"single_select","options":[{"v":"S","label":"En givare (standard är två)"},{"v":"3","label":"Tre givare"}]},{"id":"mto","step":9,"title_sv":"Specialutförande","title_en":"Made to order","required":false,"type":"single_select","options":[{"v":"X116","label":"-X116 Lufthydraulisk, turbinolja 15–300 mm/s (ø25–40, bara dubbelsidig anslutning)"},{"v":"X168","label":"-X168 Helicoil-gängor i sliden (ø20–40)"},{"v":"X210","label":"-X210 Osmord utsida, utan dammtätning"},{"v":"X322","label":"-X322 Hårdkromat cylinderrör (ø15–40)"},{"v":"X324","label":"-X324 Osmord utsida, med filtdammtätning (ø10–40)"},{"v":"X431","label":"-X431 Givarskenor på båda sidor (2 st), för korta slag med två givare"},{"v":"X2423","label":"-X2423 Gängade monteringshål i plåtarna"},{"v":"XB9","label":"-XB9 Låg hastighet 15–50 mm/s"},{"v":"XB13","label":"-XB13 Mycket låg hastighet 7–50 mm/s"}]}]}'::jsonb,
        'SMC CY1S magnetkopplad kolvstångslös cylinder, slidtyp med glidlager ø6–40', 'SMC CY1S magnetically coupled rodless cylinder, slider type with slide bearing ø6–40', 'cylinder')
