update configurator_families set
  title = 'Magnetkopplad kolvstångslös cylinder, slidtyp med kulbussning ø6–40',
  description = 'SMC CY1L magnetically coupled rodless cylinder, slider type with ball bushing bearing, ø6–40 mm, high or low magnetic holding force, adjusting bolts or shock absorbers, strokes up to 1500 mm.',
  stroke_min_mm = 1,
  stroke_max_mm = 1500,
  order_code_template = 'CY1L{bore}{port}{holding}-{stroke_mm}{adjust}-{switch}{lead}{count}-{mto}',
  rules_schema_id = 'SCHEMA-CY1L-V1'
